const std = @import("std");
const Tensor = @import("tensor.zig").Tensor;

pub const QuantumState = struct {
    amplitudes: []std.math.Complex(f32),
    num_qubits: usize,
    allocator: std.mem.Allocator,

    pub fn initZero(allocator: std.mem.Allocator, num_qubits: usize) !QuantumState {
        const size = @as(usize, 1) << @intCast(num_qubits);
        const amplitudes = try allocator.alloc(std.math.Complex(f32), size);
        for (amplitudes, 0..) |*amp, i| {
            if (i == 0) {
                amp.* = std.math.Complex(f32){ .re = 1.0, .im = 0.0 };
            } else {
                amp.* = std.math.Complex(f32){ .re = 0.0, .im = 0.0 };
            }
        }
        return QuantumState{
            .amplitudes = amplitudes,
            .num_qubits = num_qubits,
            .allocator = allocator,
        };
    }

    pub fn applyRY(self: *QuantumState, qubit: usize, angle: f32) !void {
        const cos_half = @cos(angle / 2.0);
        const sin_half = @sin(angle / 2.0);
        const size = @as(usize, 1) << @intCast(self.num_qubits);
        const stride = @as(usize, 1) << @intCast(qubit);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const amp0 = self.amplitudes[idx0];
                const amp1 = self.amplitudes[idx1];
                self.amplitudes[idx0] = std.math.Complex(f32){
                    .re = cos_half * amp0.re - sin_half * amp1.re,
                    .im = cos_half * amp0.im - sin_half * amp1.im,
                };
                self.amplitudes[idx1] = std.math.Complex(f32){
                    .re = sin_half * amp0.re + cos_half * amp1.re,
                    .im = sin_half * amp0.im + cos_half * amp1.im,
                };
            }
        }
    }

    pub fn applyRZ(self: *QuantumState, qubit: usize, angle: f32) !void {
        const exp_neg = std.math.Complex(f32){
            .re = @cos(-angle / 2.0),
            .im = @sin(-angle / 2.0),
        };
        const exp_pos = std.math.Complex(f32){
            .re = @cos(angle / 2.0),
            .im = @sin(angle / 2.0),
        };
        const size = @as(usize, 1) << @intCast(self.num_qubits);
        const stride = @as(usize, 1) << @intCast(qubit);
        var i: usize = 0;
        while (i < size) : (i += 1) {
            const bit = (i >> @intCast(qubit)) & 1;
            const phase = if (bit == 0) exp_neg else exp_pos;
            const amp = self.amplitudes[i];
            self.amplitudes[i] = std.math.Complex(f32){
                .re = amp.re * phase.re - amp.im * phase.im,
                .im = amp.re * phase.im + amp.im * phase.re,
            };
        }
    }

    pub fn applyCNOT(self: *QuantumState, control: usize, target: usize) !void {
        const size = @as(usize, 1) << @intCast(self.num_qubits);
        const control_mask = @as(usize, 1) << @intCast(control);
        const target_mask = @as(usize, 1) << @intCast(target);
        var i: usize = 0;
        while (i < size) : (i += 1) {
            if ((i & control_mask) != 0) {
                const partner = i ^ target_mask;
                if (i < partner) {
                    const temp = self.amplitudes[i];
                    self.amplitudes[i] = self.amplitudes[partner];
                    self.amplitudes[partner] = temp;
                }
            }
        }
    }

    pub fn measure(self: *QuantumState) ![]f32 {
        const result = try self.allocator.alloc(f32, self.amplitudes.len);
        for (self.amplitudes, 0..) |amp, i| {
            result[i] = amp.re * amp.re + amp.im * amp.im;
        }
        return result;
    }

    pub fn deinit(self: *QuantumState) void {
        self.allocator.free(self.amplitudes);
    }
};

pub const QuantumCircuit = struct {
    num_qubits: usize,
    parameters: []f32,
    kernel_depth: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, num_qubits: usize) !QuantumCircuit {
        const kernel_depth = 6;
        const param_count = num_qubits * kernel_depth * 3;
        const parameters = try allocator.alloc(f32, param_count);
        var prng = std.rand.DefaultPrng.init(12345);
        const random_gen = prng.random();
        for (parameters) |*p| {
            p.* = random_gen.float(f32) * 2.0 * std.math.pi;
        }
        return QuantumCircuit{
            .num_qubits = num_qubits,
            .parameters = parameters,
            .kernel_depth = kernel_depth,
            .allocator = allocator,
        };
    }

    pub fn applyParameterizedGates(self: *QuantumCircuit, state: QuantumState, layer: usize) !QuantumState {
        var result = state;
        for (0..self.num_qubits) |q| {
            const param_idx = layer * self.num_qubits * 3 + q * 3;
            try result.applyRY(q, self.parameters[param_idx]);
            try result.applyRZ(q, self.parameters[param_idx + 1]);
            try result.applyRY(q, self.parameters[param_idx + 2]);
        }
        return result;
    }

    pub fn applyEntanglement(self: *QuantumCircuit, state: QuantumState) !QuantumState {
        var result = state;
        for (0..self.num_qubits - 1) |q| {
            try result.applyCNOT(q, q + 1);
        }
        return result;
    }

    pub fn fuseChannels(self: *QuantumCircuit, states: []QuantumState) !QuantumState {
        var fused = try QuantumState.initZero(self.allocator, self.num_qubits);
        const num_channels = states.len;
        for (states, 0..) |state, ch| {
            const weight = 1.0 / @sqrt(@as(f32, @floatFromInt(num_channels)));
            for (state.amplitudes, 0..) |amp, i| {
                fused.amplitudes[i].re += amp.re * weight;
                fused.amplitudes[i].im += amp.im * weight;
            }
        }
        return fused;
    }

    pub fn measure(self: *QuantumCircuit, state: QuantumState) ![]f32 {
        return try state.measure();
    }

    pub fn updateParameters(self: *QuantumCircuit, gradients: []const f32) !void {
        const learning_rate: f32 = 0.01;
        for (self.parameters, 0..) |*p, i| {
            p.* -= learning_rate * gradients[i];
        }
    }

    pub fn deinit(self: *QuantumCircuit) void {
        self.allocator.free(self.parameters);
    }
};

pub const ClassicalEncoder = struct {
    num_channels: usize,
    encoding_dim: usize,
    weights: [][]f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, num_channels: usize) !ClassicalEncoder {
        const encoding_dim = 16;
        const weights = try allocator.alloc([]f32, num_channels);
        for (weights) |*w| {
            w.* = try allocator.alloc(f32, encoding_dim * encoding_dim);
            var prng = std.rand.DefaultPrng.init(67890);
            const random_gen = prng.random();
            for (w.*) |*val| {
                val.* = random_gen.float(f32) * 0.1;
            }
        }
        return ClassicalEncoder{
            .num_channels = num_channels,
            .encoding_dim = encoding_dim,
            .weights = weights,
            .allocator = allocator,
        };
    }

    pub fn encode(self: *ClassicalEncoder, channel_data: Tensor, channel_idx: usize) !QuantumState {
        const num_qubits = 4;
        var state = try QuantumState.initZero(self.allocator, num_qubits);
        const w = self.weights[channel_idx];
        var encoded_val: f32 = 0.0;
        for (channel_data.data, 0..) |val, i| {
            if (i < w.len) {
                encoded_val += val * w[i];
            }
        }
        const angle = encoded_val * std.math.pi;
        try state.applyRY(0, angle);
        return state;
    }

    pub fn decode(self: *ClassicalEncoder, measurement: []const f32) !Tensor {
        const output_dim = self.encoding_dim;
        const data = try self.allocator.alloc(f32, output_dim);
        for (data, 0..) |*val, i| {
            if (i < measurement.len) {
                val.* = measurement[i];
            } else {
                val.* = 0.0;
            }
        }
        const shape = try self.allocator.alloc(usize, 1);
        shape[0] = output_dim;
        return Tensor{
            .data = data,
            .shape = shape,
            .allocator = self.allocator,
        };
    }

    pub fn deinit(self: *ClassicalEncoder) void {
        for (self.weights) |w| {
            self.allocator.free(w);
        }
        self.allocator.free(self.weights);
    }
};

pub const QuantumPooling = struct {
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !QuantumPooling {
        return QuantumPooling{ .allocator = allocator };
    }

    pub fn downsample(self: *QuantumPooling, state: QuantumState) !QuantumState {
        const new_qubits = state.num_qubits - 1;
        var result = try QuantumState.initZero(self.allocator, new_qubits);
        const old_size = state.amplitudes.len;
        const new_size = result.amplitudes.len;
        for (0..new_size) |i| {
            const i0 = i * 2;
            const i1 = i0 + 1;
            if (i1 < old_size) {
                const amp0 = state.amplitudes[i0];
                const amp1 = state.amplitudes[i1];
                const norm = @sqrt(amp0.re * amp0.re + amp0.im * amp0.im + amp1.re * amp1.re + amp1.im * amp1.im);
                if (norm > 1e-8) {
                    result.amplitudes[i].re = (amp0.re + amp1.re) / norm;
                    result.amplitudes[i].im = (amp0.im + amp1.im) / norm;
                } else {
                    result.amplitudes[i].re = 0.0;
                    result.amplitudes[i].im = 0.0;
                }
            }
        }
        return result;
    }
};

pub const HybridTrainer = struct {
    learning_rate: f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !HybridTrainer {
        return HybridTrainer{
            .learning_rate = 0.01,
            .allocator = allocator,
        };
    }

    pub fn computeLoss(self: *HybridTrainer, output: Tensor, label: u32) !f32 {
        _ = self;
        var max_val: f32 = -1e9;
        var max_idx: usize = 0;
        for (output.data, 0..) |val, i| {
            if (val > max_val) {
                max_val = val;
                max_idx = i;
            }
        }
        const predicted = @as(u32, @intCast(max_idx));
        const loss = if (predicted == label) 0.0 else 1.0;
        return loss;
    }

    pub fn backpropagate(self: *HybridTrainer, loss: f32) ![]f32 {
        const num_params = 72;
        const gradients = try self.allocator.alloc(f32, num_params);
        for (gradients) |*g| {
            g.* = loss * 0.001;
        }
        return gradients;
    }
};

pub const MultiChannelQCNN = struct {
    num_channels: usize,
    num_qubits: usize,
    circuit: QuantumCircuit,
    classical_encoder: ClassicalEncoder,
    quantum_pooling: QuantumPooling,
    hybrid_trainer: HybridTrainer,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, channels: usize, qubits: usize) !MultiChannelQCNN {
        return MultiChannelQCNN{
            .num_channels = channels,
            .num_qubits = qubits,
            .circuit = try QuantumCircuit.init(allocator, qubits),
            .classical_encoder = try ClassicalEncoder.init(allocator, channels),
            .quantum_pooling = try QuantumPooling.init(allocator),
            .hybrid_trainer = try HybridTrainer.init(allocator),
            .allocator = allocator,
        };
    }

    pub fn encodeMultiChannel(self: *MultiChannelQCNN, input: []const Tensor) !QuantumState {
        var encoded_states = try self.allocator.alloc(QuantumState, self.num_channels);
        defer {
            for (encoded_states) |*s| {
                s.deinit();
            }
            self.allocator.free(encoded_states);
        }
        for (input, 0..) |channel_data, i| {
            encoded_states[i] = try self.classical_encoder.encode(channel_data, i);
        }
        return try self.circuit.fuseChannels(encoded_states);
    }

    pub fn applyQuantumConvolution(self: *MultiChannelQCNN, state: QuantumState) !QuantumState {
        var result = state;
        for (0..self.circuit.kernel_depth) |layer| {
            const temp = try self.circuit.applyParameterizedGates(result, layer);
            if (layer > 0) {
                result.deinit();
            }
            result = temp;
            const entangled = try self.circuit.applyEntanglement(result);
            result.deinit();
            result = entangled;
        }
        return result;
    }

    pub fn quantumPooling(self: *MultiChannelQCNN, state: QuantumState) !QuantumState {
        return try self.quantum_pooling.downsample(state);
    }

    pub fn hybridTrainingStep(self: *MultiChannelQCNN, batch: []const []const Tensor, labels: []const u32) !f32 {
        var total_loss: f32 = 0.0;
        for (batch, 0..) |input, i| {
            const quantum_state = try self.encodeMultiChannel(input);
            defer quantum_state.deinit();
            const conv_state = try self.applyQuantumConvolution(quantum_state);
            defer conv_state.deinit();
            const pooled_state = try self.quantumPooling(conv_state);
            defer pooled_state.deinit();
            const measurement = try self.circuit.measure(pooled_state);
            defer self.allocator.free(measurement);
            const classical_output = try self.classical_encoder.decode(measurement);
            defer classical_output.deinit();
            const loss = try self.hybrid_trainer.computeLoss(classical_output, labels[i]);
            total_loss += loss;
            const gradients = try self.hybrid_trainer.backpropagate(loss);
            defer self.allocator.free(gradients);
            try self.circuit.updateParameters(gradients);
        }
        return total_loss / @as(f32, @floatFromInt(batch.len));
    }

    pub fn deinit(self: *MultiChannelQCNN) void {
        self.circuit.deinit();
        self.classical_encoder.deinit();
    }
};

pub const QuantumLayer = struct {
    qubits: usize,
    parameters: []f32,
    gate_sequence: []QuantumGate,
    allocator: std.mem.Allocator,

    pub fn initLean(allocator: std.mem.Allocator, qubits: usize) !QuantumLayer {
        const param_count = qubits * 3;
        const gate_count = qubits * 2;
        const parameters = try allocator.alloc(f32, param_count);
        const gate_sequence = try allocator.alloc(QuantumGate, gate_count);
        var prng = std.rand.DefaultPrng.init(11111);
        const random_gen = prng.random();
        for (parameters) |*p| {
            p.* = random_gen.float(f32) * 2.0 * std.math.pi;
        }
        for (gate_sequence, 0..) |*gate, i| {
            gate.* = QuantumGate{
                .gate_type = if (i % 2 == 0) GateType.RY else GateType.CNOT,
                .qubit = i / 2,
                .parameter = parameters[i % param_count],
            };
        }
        return QuantumLayer{
            .qubits = qubits,
            .parameters = parameters,
            .gate_sequence = gate_sequence,
            .allocator = allocator,
        };
    }

    pub fn encodeWithMinimalGates(self: *QuantumLayer, input: Tensor) !QuantumState {
        var state = try QuantumState.initZero(self.allocator, self.qubits);
        for (0..self.qubits) |i| {
            const angle = if (i < input.data.len) input.data[i] * std.math.pi else 0.0;
            try state.applyRY(i, angle);
        }
        return state;
    }

    pub fn applyLeanCircuit(self: *QuantumLayer, state: QuantumState) !QuantumState {
        var current = state;
        for (self.gate_sequence) |gate| {
            const new_state = try gate.apply(current, self.allocator);
            if (gate.gate_type != GateType.CNOT) {
                current.deinit();
            }
            current = new_state;
        }
        return current;
    }

    pub fn parameterShiftRule(self: *QuantumLayer, input: Tensor, loss: f32) ![]f32 {
        const shift = std.math.pi / 2.0;
        var gradients = try self.allocator.alloc(f32, self.parameters.len);
        for (self.parameters, 0..) |param, i| {
            self.parameters[i] = param + shift;
            const loss_plus = try self.evaluateLoss(input, loss);
            self.parameters[i] = param - shift;
            const loss_minus = try self.evaluateLoss(input, loss);
            self.parameters[i] = param;
            gradients[i] = (loss_plus - loss_minus) / 2.0;
        }
        return gradients;
    }

    pub fn evaluateLoss(self: *QuantumLayer, input: Tensor, base_loss: f32) !f32 {
        const state = try self.encodeWithMinimalGates(input);
        defer state.deinit();
        const processed = try self.applyLeanCircuit(state);
        defer processed.deinit();
        const measurement = try processed.measure();
        defer self.allocator.free(measurement);
        var sum: f32 = 0.0;
        for (measurement) |val| {
            sum += val;
        }
        return base_loss + sum * 0.001;
    }

    pub fn updateWithAdam(self: *QuantumLayer, gradients: []const f32, epoch: usize) !void {
        const learning_rate: f32 = 0.001;
        const decay = 0.9 + @as(f32, @floatFromInt(epoch)) * 0.0001;
        for (self.parameters, 0..) |*p, i| {
            p.* -= learning_rate * gradients[i] * decay;
        }
    }

    pub fn deinit(self: *QuantumLayer) void {
        self.allocator.free(self.parameters);
        self.allocator.free(self.gate_sequence);
    }
};

pub const GateType = enum {
    RY,
    RZ,
    CNOT,
};

pub const QuantumGate = struct {
    gate_type: GateType,
    qubit: usize,
    parameter: f32,

    pub fn apply(self: QuantumGate, state: QuantumState, allocator: std.mem.Allocator) !QuantumState {
        var result = try QuantumState.initZero(allocator, state.num_qubits);
        @memcpy(result.amplitudes, state.amplitudes);
        switch (self.gate_type) {
            .RY => try result.applyRY(self.qubit, self.parameter),
            .RZ => try result.applyRZ(self.qubit, self.parameter),
            .CNOT => {
                const target = if (self.qubit + 1 < state.num_qubits) self.qubit + 1 else 0;
                try result.applyCNOT(self.qubit, target);
            },
        }
        return result;
    }
};

pub const ClassicalHead = struct {
    input_dim: usize,
    output_dim: usize,
    weights: []f32,
    bias: []f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, input_dim: usize) !ClassicalHead {
        const output_dim = 10;
        const weights = try allocator.alloc(f32, input_dim * output_dim);
        const bias = try allocator.alloc(f32, output_dim);
        var prng = std.rand.DefaultPrng.init(22222);
        const random_gen = prng.random();
        for (weights) |*w| {
            w.* = random_gen.float(f32) * 0.1;
        }
        for (bias) |*b| {
            b.* = random_gen.float(f32) * 0.01;
        }
        return ClassicalHead{
            .input_dim = input_dim,
            .output_dim = output_dim,
            .weights = weights,
            .bias = bias,
            .allocator = allocator,
        };
    }

    pub fn classify(self: *ClassicalHead, input: []const f32) !Tensor {
        const output = try self.allocator.alloc(f32, self.output_dim);
        for (0..self.output_dim) |i| {
            var sum: f32 = self.bias[i];
            for (0..self.input_dim) |j| {
                const weight_idx = i * self.input_dim + j;
                const input_val = if (j < input.len) input[j] else 0.0;
                sum += self.weights[weight_idx] * input_val;
            }
            output[i] = sum;
        }
        const shape = try self.allocator.alloc(usize, 1);
        shape[0] = self.output_dim;
        return Tensor{
            .data = output,
            .shape = shape,
            .allocator = self.allocator,
        };
    }

    pub fn deinit(self: *ClassicalHead) void {
        self.allocator.free(self.weights);
        self.allocator.free(self.bias);
    }
};

pub const LeanCQHNN = struct {
    num_qubits: usize,
    quantum_layer: QuantumLayer,
    classical_head: ClassicalHead,
    parameter_count: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, qubits: usize) !LeanCQHNN {
        return LeanCQHNN{
            .num_qubits = qubits,
            .quantum_layer = try QuantumLayer.initLean(allocator, qubits),
            .classical_head = try ClassicalHead.init(allocator, qubits * 2),
            .parameter_count = qubits * 3,
            .allocator = allocator,
        };
    }

    pub fn forwardLean(self: *LeanCQHNN, input: Tensor) !Tensor {
        const quantum_encoded = try self.quantum_layer.encodeWithMinimalGates(input);
        defer quantum_encoded.deinit();
        const quantum_processed = try self.quantum_layer.applyLeanCircuit(quantum_encoded);
        defer quantum_processed.deinit();
        const measured = try self.quantum_layer.efficientMeasurement(quantum_processed);
        defer self.allocator.free(measured);
        return try self.classical_head.classify(measured);
    }

    pub fn trainOnLimitedResources(self: *LeanCQHNN, dataset: []const TrainingSample, epochs: usize) !void {
