            var epoch_loss: f32 = 0.0;
            for (dataset) |sample| {
                const output = try self.forwardLean(sample.input);
                defer output.deinit();
                const loss = try self.computeLoss(output, sample.label);
                epoch_loss += loss;
                const param_gradients = try self.quantum_layer.parameterShiftRule(sample.input, loss);
                defer self.allocator.free(param_gradients);
                try self.quantum_layer.updateWithAdam(param_gradients, epoch);
            }
            std.debug.print("Epoch {d}: Loss = {d:.6}\n", .{ epoch, epoch_loss / @as(f32, @floatFromInt(dataset.len)) });
        }
    }

    pub fn computeLoss(self: *LeanCQHNN, output: Tensor, label: u32) !f32 {
        _ = self;
        var max_val: f32 = -1e9;
        var max_idx: usize = 0;
        for (output.data, 0..) |val, i| {
            if (val > max_val) {
                max_val = val;
                max_idx = i;
            }
        }
        const predicted = @as(u32, @intCast(max_idx));
        return if (predicted == label) 0.0 else 1.0;
    }

    pub fn deinit(self: *LeanCQHNN) void {
        self.quantum_layer.deinit();
        self.classical_head.deinit();
    }
};

