        return compressed;
    }

    pub fn wavelengthDivisionMultiplex(self: *OpticalInterconnect, state: OpticalState) ![]OpticalState {
        var channels = try self.allocator.alloc(OpticalState, self.num_wavelengths);
        const channel_size = (state.phase.len + self.num_wavelengths - 1) / self.num_wavelengths;
        for (0..self.num_wavelengths) |ch| {
            channels[ch] = try OpticalState.init(self.allocator, channel_size, 1);
            const start = ch * channel_size;
            const end = @min(start + channel_size, state.phase.len);
            for (start..end, 0..) |i, j| {
                if (j < channel_size) {
                    channels[ch].phase[j] = state.phase[i];
                    channels[ch].amplitude[j] = state.amplitude[i];
                }
            }
        }
        return channels;
    }

    pub fn combineChannels(self: *OpticalInterconnect, channels: []OpticalState) !OpticalState {
        var total_size: usize = 0;
        for (channels) |ch| {
            total_size += ch.phase.len;
        }
        var combined = try OpticalState.init(self.allocator, total_size, self.num_wavelengths);
        var offset: usize = 0;
        for (channels) |ch| {
            @memcpy(combined.phase[offset..offset + ch.phase.len], ch.phase);
            @memcpy(combined.amplitude[offset..offset + ch.amplitude.len], ch.amplitude);
            offset += ch.phase.len;
        }
        return combined;
    }
};

pub const BayesianOpticalTrainer = struct {
    prior_mean: []f32,
    prior_variance: []f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !BayesianOpticalTrainer {
        const param_size = 1024;
        const prior_mean = try allocator.alloc(f32, param_size);
        const prior_variance = try allocator.alloc(f32, param_size);
        @memset(prior_mean, 0.0);
        @memset(prior_variance, 1.0);
        return BayesianOpticalTrainer{
            .prior_mean = prior_mean,
            .prior_variance = prior_variance,
            .allocator = allocator,
        };
    }

    pub fn computePrior(self: *BayesianOpticalTrainer, states: []OpticalState) ![]f32 {
        const prior = try self.allocator.alloc(f32, self.prior_mean.len);
        @memcpy(prior, self.prior_mean);
        for (states) |state| {
            for (0..@min(state.phase.len, prior.len)) |i| {
                prior[i] += state.phase[i] * 0.001;
            }
        }
        return prior;
    }

    pub fn evaluateLikelihood(self: *BayesianOpticalTrainer, states: []OpticalState) ![]f32 {
        const likelihood = try self.allocator.alloc(f32, self.prior_mean.len);
        @memset(likelihood, 1.0);
        for (states) |state| {
            for (0..@min(state.amplitude.len, likelihood.len)) |i| {
                const diff = state.amplitude[i] - self.prior_mean[i];
                const exp_val = @exp(-diff * diff / (2.0 * self.prior_variance[i]));
                likelihood[i] *= exp_val;
            }
        }
        return likelihood;
    }

    pub fn updatePosterior(self: *BayesianOpticalTrainer, prior: []const f32, likelihood: []const f32) ![]f32 {
        const posterior = try self.allocator.alloc(f32, prior.len);
        var sum: f32 = 0.0;
        for (0..prior.len) |i| {
            posterior[i] = prior[i] * likelihood[i];
            sum += posterior[i];
        }
        if (sum > 1e-8) {
            for (posterior) |*val| {
                val.* /= sum;
            }
        }
        return posterior;
    }

    pub fn deinit(self: *BayesianOpticalTrainer) void {
        self.allocator.free(self.prior_mean);
        self.allocator.free(self.prior_variance);
    }
};

pub const PhotonicNeuralCore = struct {
    photonic_neurons: usize,
    optical_latent_dim: usize,
    meta_surfaces: []MetaSurface,
    optical_interconnect: OpticalInterconnect,
    bayes_trainer: BayesianOpticalTrainer,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, neurons: usize) !PhotonicNeuralCore {
        const latent_dim = @as(usize, @intFromFloat(@sqrt(@as(f64, @floatFromInt(neurons)))));
        var meta_surfaces = try allocator.alloc(MetaSurface, 16);
        for (meta_surfaces) |*surface| {
            surface.* = try MetaSurface.init(allocator, 256);
        }
        return PhotonicNeuralCore{
            .photonic_neurons = neurons,
            .optical_latent_dim = latent_dim,
            .meta_surfaces = meta_surfaces,
            .optical_interconnect = try OpticalInterconnect.init(allocator),
            .bayes_trainer = try BayesianOpticalTrainer.init(allocator),
            .allocator = allocator,
        };
    }

    pub fn encodeToOpticalLatent(self: *PhotonicNeuralCore, input: Tensor) !OpticalState {
        var phase_modulated = try self.optical_interconnect.modulatePhase(input);
        defer phase_modulated.deinit();
        var current = phase_modulated;
        for (self.meta_surfaces, 0..) |*surface, i| {
            const transformed = try surface.transform(current);
            if (i > 0) {
                current.deinit();
            }
            current = transformed;
        }
        return try self.optical_interconnect.compressToLatent(current, self.optical_latent_dim);
    }

    pub fn generateAtLightSpeed(self: *PhotonicNeuralCore, latent: OpticalState) !OpticalState {
        var current = latent;
        for (0..12) |layer| {
            const wavelength_channels = try self.optical_interconnect.wavelengthDivisionMultiplex(current);
            defer {
                for (wavelength_channels) |*ch| {
                    ch.deinit();
                }
                self.allocator.free(wavelength_channels);
            }
            var processed_channels = try self.allocator.alloc(OpticalState, wavelength_channels.len);
            for (wavelength_channels, 0..) |channel, i| {
                processed_channels[i] = try self.processPhotonically(channel, layer);
            }
            defer {
                for (processed_channels) |*ch| {
                    ch.deinit();
                }
                self.allocator.free(processed_channels);
            }
            const combined = try self.optical_interconnect.combineChannels(processed_channels);
            if (layer > 0) {
                current.deinit();
            }
            current = combined;
        }
        return current;
    }

    pub fn processPhotonically(self: *PhotonicNeuralCore, channel: OpticalState, layer: usize) !OpticalState {
        const surface_idx = layer % self.meta_surfaces.len;
        return try self.meta_surfaces[surface_idx].transform(channel);
    }

    pub fn bayesianOpticalTraining(self: *PhotonicNeuralCore, dataset: []const Tensor, iterations: usize) !void {
        for (0..iterations) |iter| {
            const batch = try self.sampleBatch(dataset, 32);
            defer self.allocator.free(batch);
            var optical_states = try self.allocator.alloc(OpticalState, batch.len);
            defer {
                for (optical_states) |*state| {
                    state.deinit();
                }
                self.allocator.free(optical_states);
            }
            for (batch, 0..) |sample, i| {
                optical_states[i] = try self.encodeToOpticalLatent(sample);
            }
            const prior = try self.bayes_trainer.computePrior(optical_states);
            defer self.allocator.free(prior);
            const likelihood = try self.bayes_trainer.evaluateLikelihood(optical_states);
            defer self.allocator.free(likelihood);
            const posterior = try self.bayes_trainer.updatePosterior(prior, likelihood);
            defer self.allocator.free(posterior);
            try self.updateMetaSurfaces(posterior);
            if (iter % 100 == 0) {
                const energy_per_inference = try self.measureEnergyEfficiency();
                std.debug.print("Iteration {d}: Energy = {d:.3} pJ/inference\n", .{ iter, energy_per_inference });
            }
        }
    }

    fn sampleBatch(self: *PhotonicNeuralCore, dataset: []const Tensor, batch_size: usize) ![]Tensor {
        const actual_size = @min(batch_size, dataset.len);
        const batch = try self.allocator.alloc(Tensor, actual_size);
        for (0..actual_size) |i| {
            batch[i] = dataset[i];
        }
        return batch;
    }

    fn updateMetaSurfaces(self: *PhotonicNeuralCore, posterior: []const f32) !void {
        for (self.meta_surfaces) |*surface| {
            for (surface.transform_matrix, 0..) |*val, i| {
                if (i < posterior.len) {
                    val.* += posterior[i] * 0.0001;
                }
            }
        }
    }

    fn measureEnergyEfficiency(self: *PhotonicNeuralCore) !f64 {
        const photonic_energy_per_op = 0.000001;
        const ops_per_inference = @as(f64, @floatFromInt(self.photonic_neurons)) * 1000.0;
        return photonic_energy_per_op * ops_per_inference;
    }

    pub fn deinit(self: *PhotonicNeuralCore) void {
        for (self.meta_surfaces) |*surface| {
            surface.deinit();
        }
        self.allocator.free(self.meta_surfaces);
        self.bayes_trainer.deinit();
    }
};

pub const Event = struct {
    timestamp: u64,
    value: f32,
};

pub const EventQueue = struct {
    events: []Event,
    head: usize,
    tail: usize,
    capacity: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !EventQueue {
        return EventQueue{
            .events = try allocator.alloc(Event, capacity),
            .head = 0,
            .tail = 0,
            .capacity = capacity,
            .allocator = allocator,
        };
    }

    pub fn push(self: *EventQueue, event: Event) !void {
        if ((self.tail + 1) % self.capacity == self.head) {
            return error.QueueFull;
        }
        self.events[self.tail] = event;
        self.tail = (self.tail + 1) % self.capacity;
    }

    pub fn pop(self: *EventQueue, count: usize) ![]f32 {
        const actual_count = @min(count, self.size());
        const result = try self.allocator.alloc(f32, actual_count);
        for (0..actual_count) |i| {
            result[i] = self.events[(self.head + i) % self.capacity].value;
        }
        self.head = (self.head + actual_count) % self.capacity;
        return result;
    }

    pub fn shouldProcess(self: *EventQueue) bool {
        return self.size() >= 32;
    }

    fn size(self: *EventQueue) usize {
        if (self.tail >= self.head) {
            return self.tail - self.head;
        } else {
            return self.capacity - self.head + self.tail;
        }
    }

    pub fn deinit(self: *EventQueue) void {
        self.allocator.free(self.events);
    }
};

pub const SSMMatrices = struct {
    A: []f32,
    B: []f32,
    C: []f32,
    state_dim: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, state_dim: usize) !SSMMatrices {
        const A = try allocator.alloc(f32, state_dim * state_dim);
        const B = try allocator.alloc(f32, state_dim * state_dim);
        const C = try allocator.alloc(f32, state_dim * state_dim);
        var prng = std.rand.DefaultPrng.init(44444);
        const random_gen = prng.random();
        for (A) |*val| {
            val.* = random_gen.float(f32) * 0.1;
        }
        for (B) |*val| {
            val.* = random_gen.float(f32) * 0.1;
        }
        for (C) |*val| {
            val.* = random_gen.float(f32) * 0.1;
        }
        return SSMMatrices{
            .A = A,
            .B = B,
            .C = C,
            .state_dim = state_dim,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SSMMatrices) void {
        self.allocator.free(self.A);
        self.allocator.free(self.B);
        self.allocator.free(self.C);
    }
};

pub const CIMCrossbar = struct {
    rows: usize,
    cols: usize,
    conductance: []f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, rows: usize, cols: usize) !CIMCrossbar {
        const conductance = try allocator.alloc(f32, rows * cols);
        var prng = std.rand.DefaultPrng.init(55555);
        const random_gen = prng.random();
        for (conductance) |*val| {
            val.* = random_gen.float(f32) * 0.01;
        }
        return CIMCrossbar{
            .rows = rows,
            .cols = cols,
            .conductance = conductance,
            .allocator = allocator,
        };
    }

    pub fn matrixVectorMultiply(self: *CIMCrossbar, matrix: []const f32, vector: []const f32) ![]f32 {
        const result = try self.allocator.alloc(f32, self.rows);
        for (0..self.rows) |i| {
            var sum: f32 = 0.0;
            for (0..@min(self.cols, vector.len)) |j| {
                const idx = i * self.cols + j;
                if (idx < matrix.len) {
                    sum += matrix[idx] * vector[j] * self.conductance[idx];
                }
            }
            result[i] = sum;
        }
        return result;
    }

    pub fn deinit(self: *CIMCrossbar) void {
        self.allocator.free(self.conductance);
    }
};

pub const ComputeInMemorySSM = struct {
    state_dim: usize,
    sequence_length: usize,
    cim_array: CIMCrossbar,
    ssm_matrices: SSMMatrices,
    event_queue: EventQueue,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, state_dim: usize, seq_len: usize) !ComputeInMemorySSM {
        return ComputeInMemorySSM{
            .state_dim = state_dim,
            .sequence_length = seq_len,
            .cim_array = try CIMCrossbar.init(allocator, state_dim, state_dim),
            .ssm_matrices = try SSMMatrices.init(allocator, state_dim),
            .event_queue = try EventQueue.init(allocator, seq_len * 2),
            .allocator = allocator,
        };
    }

    pub fn processEventDriven(self: *ComputeInMemorySSM, input_events: []const Event) !Tensor {
        var hidden_state = try Tensor.zeros(self.allocator, &[_]usize{self.state_dim});
        defer hidden_state.deinit();
        for (input_events) |event| {
            try self.event_queue.push(event);
            if (self.event_queue.shouldProcess()) {
                const batch_events = try self.event_queue.pop(32);
                defer self.allocator.free(batch_events);
                const A_h = try self.cim_array.matrixVectorMultiply(self.ssm_matrices.A, hidden_state.data);
                defer self.allocator.free(A_h);
                const B_x = try self.cim_array.matrixVectorMultiply(self.ssm_matrices.B, batch_events);
                defer self.allocator.free(B_x);
                for (0..self.state_dim) |i| {
                    if (i < A_h.len and i < B_x.len) {
                        hidden_state.data[i] = A_h[i] + B_x[i];
                    }
                }
            }
        }
        const output = try self.cim_array.matrixVectorMultiply(self.ssm_matrices.C, hidden_state.data);
        return Tensor.fromSlice(self.allocator, output, &[_]usize{output.len});
    }

    pub fn efficientLongRangeProcessing(self: *ComputeInMemorySSM, sequence: Tensor) !Tensor {
        const chunk_size = 1024;
        const num_chunks = (self.sequence_length + chunk_size - 1) / chunk_size;
        var outputs = try self.allocator.alloc(Tensor, num_chunks);
        defer {
            for (outputs) |*out| {
                out.deinit();
            }
            self.allocator.free(outputs);
        }
        for (0..num_chunks) |chunk_idx| {
            const start = chunk_idx * chunk_size;
            const end = @min(start + chunk_size, self.sequence_length);
            const chunk = sequence.slice(start, end);
            const chunk_events = try self.convertToEvents(chunk);
            defer self.allocator.free(chunk_events);
            outputs[chunk_idx] = try self.processEventDriven(chunk_events);
        }
        return try Tensor.concatenate(self.allocator, outputs);
    }

    fn convertToEvents(self: *ComputeInMemorySSM, chunk: Tensor) ![]Event {
        const events = try self.allocator.alloc(Event, chunk.data.len);
        for (chunk.data, 0..) |val, i| {
            events[i] = Event{
                .timestamp = i,
                .value = val,
            };
        }
        return events;
    }

    pub fn deinit(self: *ComputeInMemorySSM) void {
        self.cim_array.deinit();
        self.ssm_matrices.deinit();
        self.event_queue.deinit();
    }
};

pub const LLMConfig = struct {
    num_layers: usize,
