pub const PIMUnit = struct {
    compute_id: usize,
    memory_bank: usize,

    pub fn matmulInMemory(self: *PIMUnit, input: []const f32, weights: []const f32) ![]f32 {
        _ = self;
        const output_size = @min(input.len, weights.len / input.len);
        const allocator = std.heap.page_allocator;
        const output = try allocator.alloc(f32, output_size);
        for (0..output_size) |i| {
            var sum: f32 = 0.0;
            for (0..input.len) |j| {
                const w_idx = i * input.len + j;
                if (w_idx < weights.len) {
                    sum += input[j] * weights[w_idx];
                }
            }
            output[i] = sum;
        }
        return output;
    }

    pub fn softmaxInMemory(self: *PIMUnit, input: []const f32) ![]f32 {
        _ = self;
        const allocator = std.heap.page_allocator;
        const output = try allocator.alloc(f32, input.len);
        var max_val: f32 = input[0];
        for (input) |val| {
            if (val > max_val) max_val = val;
        }
        var sum: f32 = 0.0;
        for (input, 0..) |val, i| {
            output[i] = @exp(val - max_val);
            sum += output[i];
        }
        for (output) |*val| {
            val.* /= sum;
        }
        return output;
    }

    pub fn geluInMemory(self: *PIMUnit, input: []const f32) ![]f32 {
        _ = self;
        const allocator = std.heap.page_allocator;
        const output = try allocator.alloc(f32, input.len);
        for (input, 0..) |val, i| {
            const cdf = 0.5 * (1.0 + std.math.tanh(std.math.sqrt(2.0 / std.math.pi) * (val + 0.044715 * val * val * val)));
            output[i] = val * cdf;
        }
        return output;
    }
};

pub const PIMComputeUnit = struct {
    unit_id: usize,
    weights_cache: std.StringHashMap([]f32),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, unit_id: usize) !PIMComputeUnit {
        return PIMComputeUnit{
            .unit_id = unit_id,
            .weights_cache = std.StringHashMap([]f32).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn matmulInMemory(self: *PIMComputeUnit, input: []const f32, weights: []const f32) ![]f32 {
        const output_size = weights.len / input.len;
        const output = try self.allocator.alloc(f32, output_size);
        for (0..output_size) |i| {
            var sum: f32 = 0.0;
            for (0..input.len) |j| {
                sum += input[j] * weights[i * input.len + j];
            }
            output[i] = sum;
        }
        return output;
    }

    pub fn softmaxInMemory(self: *PIMComputeUnit, input: []const f32) ![]f32 {
        const output = try self.allocator.alloc(f32, input.len);
        var max_val: f32 = input[0];
        for (input) |val| {
            if (val > max_val) max_val = val;
        }
        var sum: f32 = 0.0;
        for (input, 0..) |val, i| {
            output[i] = @exp(val - max_val);
            sum += output[i];
        }
        for (output) |*val| {
            val.* /= sum;
        }
        return output;
    }

    pub fn geluInMemory(self: *PIMComputeUnit, input: []const f32) ![]f32 {
        const output = try self.allocator.alloc(f32, input.len);
        for (input, 0..) |val, i| {
            const cdf = 0.5 * (1.0 + std.math.tanh(std.math.sqrt(2.0 / std.math.pi) * (val + 0.044715 * val * val * val)));
            output[i] = val * cdf;
        }
        return output;
    }

    pub fn deinit(self: *PIMComputeUnit) void {
        var iter = self.weights_cache.iterator();
        while (iter.next()) |entry| {
            self.allocator.free(entry.value_ptr.*);
        }
        self.weights_cache.deinit();
    }
};

pub const MemoryBank = struct {
    bank_id: usize,
    data: []f32,
