pub const GDDR6AiMChip = struct {
    memory_banks: [8]MemoryBank,
    compute_units: [64]PIMComputeUnit,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !GDDR6AiMChip {
        var chip: GDDR6AiMChip = undefined;
        chip.allocator = allocator;
        for (&chip.memory_banks, 0..) |*bank, i| {
            bank.* = try MemoryBank.init(allocator, i, 1048576);
        }
        for (&chip.compute_units, 0..) |*unit, i| {
            unit.* = try PIMComputeUnit.init(allocator, i);
        }
        return chip;
    }

    pub fn selfAttentionPIM(self: *GDDR6AiMChip, input: []f32, layer: usize) ![]f32 {
        const Q_weights = try self.getWeights("Q", layer);
        defer self.allocator.free(Q_weights);
        const K_weights = try self.getWeights("K", layer);
        defer self.allocator.free(K_weights);
        const V_weights = try self.getWeights("V", layer);
        defer self.allocator.free(V_weights);
        const Q = try self.compute_units[0].matmulInMemory(input, Q_weights);
        defer self.allocator.free(Q);
        const K = try self.compute_units[1].matmulInMemory(input, K_weights);
        defer self.allocator.free(K);
        const V = try self.compute_units[2].matmulInMemory(input, V_weights);
        defer self.allocator.free(V);
        const scores = try self.compute_units[3].matmulInMemory(Q, K);
        defer self.allocator.free(scores);
        const attn = try self.compute_units[4].softmaxInMemory(scores);
        defer self.allocator.free(attn);
        const output = try self.compute_units[5].matmulInMemory(attn, V);
        return output;
    }

    pub fn feedForwardPIM(self: *GDDR6AiMChip, input: []f32, layer: usize) ![]f32 {
        const FF1_weights = try self.getWeights("FF1", layer);
        defer self.allocator.free(FF1_weights);
        const FF2_weights = try self.getWeights("FF2", layer);
        defer self.allocator.free(FF2_weights);
        const ff1 = try self.compute_units[6].matmulInMemory(input, FF1_weights);
        defer self.allocator.free(ff1);
        const activated = try self.compute_units[7].geluInMemory(ff1);
        defer self.allocator.free(activated);
        const ff2 = try self.compute_units[8].matmulInMemory(activated, FF2_weights);
        return ff2;
    }

    fn getWeights(self: *GDDR6AiMChip, weight_type: []const u8, layer: usize) ![]f32 {
        _ = weight_type;
        const bank_idx = layer % 8;
        const size = 4096 * 4096;
        const weights = try self.allocator.alloc(f32, size);
        @memcpy(weights[0..@min(size, self.memory_banks[bank_idx].data.len)], self.memory_banks[bank_idx].data[0..@min(size, self.memory_banks[bank_idx].data.len)]);
        return weights;
    }

    pub fn deinit(self: *GDDR6AiMChip) void {
        for (&self.memory_banks) |*bank| {
            bank.deinit();
        }
        for (&self.compute_units) |*unit| {
            unit.deinit();
        }
    }
};

pub const AiMXAccelerator = struct {
    gddr6_aim_chips: []GDDR6AiMChip,
    pim_units: []PIMUnit,
    llm_config: LLMConfig,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, num_chips: usize) !AiMXAccelerator {
        var gddr6_chips = try allocator.alloc(GDDR6AiMChip, num_chips);
        for (gddr6_chips) |*chip| {
            chip.* = try GDDR6AiMChip.init(allocator);
        }
        const pim_units = try allocator.alloc(PIMUnit, num_chips * 8);
        for (pim_units, 0..) |*unit, i| {
            unit.* = PIMUnit{
                .compute_id = i,
                .memory_bank = i / 8,
            };
        }
        return AiMXAccelerator{
            .gddr6_aim_chips = gddr6_chips,
            .pim_units = pim_units,
            .llm_config = try LLMConfig.initForLLM(allocator),
            .allocator = allocator,
        };
    }

    pub fn processLLMInference(self: *AiMXAccelerator, tokens: []const u32) ![]f32 {
        const embeddings = try self.embed(tokens);
        defer self.allocator.free(embeddings);
        var hidden = embeddings;
        for (0..self.llm_config.num_layers) |layer| {
            const new_hidden = try self.transformerLayerInMemory(hidden, layer);
            if (layer > 0) {
                self.allocator.free(hidden);
            }
            hidden = new_hidden;
        }
        return try self.computeLogits(hidden);
    }

    fn embed(self: *AiMXAccelerator, tokens: []const u32) ![]f32 {
        const embedding_dim = self.llm_config.hidden_dim;
        const embeddings = try self.allocator.alloc(f32, tokens.len * embedding_dim);
        var prng = std.rand.DefaultPrng.init(66666);
        const random_gen = prng.random();
        for (embeddings) |*val| {
            val.* = random_gen.float(f32) * 0.02 - 0.01;
        }
        return embeddings;
    }

    fn transformerLayerInMemory(self: *AiMXAccelerator, input: []f32, layer: usize) ![]f32 {
        const chip_idx = layer % self.gddr6_aim_chips.len;
        const chip = &self.gddr6_aim_chips[chip_idx];
        const attn_out = try chip.selfAttentionPIM(input, layer);
        defer self.allocator.free(attn_out);
        const ffn_out = try chip.feedForwardPIM(attn_out, layer);
        return ffn_out;
    }

    fn computeLogits(self: *AiMXAccelerator, hidden: []const f32) ![]f32 {
        const vocab_size = 50257;
        const logits = try self.allocator.alloc(f32, vocab_size);
        for (0..vocab_size) |i| {
            var sum: f32 = 0.0;
            for (hidden, 0..) |h, j| {
                sum += h * @sin(@as(f32, @floatFromInt(i * j)));
            }
            logits[i] = sum;
        }
        return logits;
    }

    pub fn deinit(self: *AiMXAccelerator) void {
        for (self.gddr6_aim_chips) |*chip| {
            chip.deinit();
        }
        self.allocator.free(self.gddr6_aim_chips);
        self.allocator.free(self.pim_units);
    }
};
