const std = @import("std");

pub const Tensor = struct {
    data: []f32,
    shape: []usize,
    strides: []usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        var total_size: usize = 1;
        for (shape) |dim| {
            total_size *= dim;
        }
        const data = try allocator.alloc(f32, total_size);
        const shape_copy = try allocator.alloc(usize, shape.len);
        @memcpy(shape_copy, shape);
        const strides = try allocator.alloc(usize, shape.len);
        var stride: usize = 1;
        var i: usize = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }
        return Tensor{
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .allocator = allocator,
        };
    }

    pub fn zeros(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        var tensor = try init(allocator, shape);
        @memset(tensor.data, 0.0);
        return tensor;
    }

    pub fn ones(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        var tensor = try init(allocator, shape);
        @memset(tensor.data, 1.0);
        return tensor;
    }

    pub fn random(allocator: std.mem.Allocator, shape: []const usize, seed: u64) !Tensor {
        var tensor = try init(allocator, shape);
        var prng = std.rand.DefaultPrng.init(seed);
        const random_gen = prng.random();
        for (tensor.data) |*val| {
            val.* = random_gen.float(f32) * 2.0 - 1.0;
        }
        return tensor;
    }

    pub fn fromSlice(allocator: std.mem.Allocator, slice: []const f32, shape: []const usize) !Tensor {
        var tensor = try init(allocator, shape);
        @memcpy(tensor.data, slice);
        return tensor;
    }

    pub fn reshape(self: Tensor, allocator: std.mem.Allocator, new_shape: []const usize) !Tensor {
        var new_total: usize = 1;
        for (new_shape) |dim| {
            new_total *= dim;
        }
        if (new_total != self.data.len) {
            return error.IncompatibleShape;
        }
        const shape_copy = try allocator.alloc(usize, new_shape.len);
        @memcpy(shape_copy, new_shape);
        const strides = try allocator.alloc(usize, new_shape.len);
        var stride: usize = 1;
        var i: usize = new_shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= new_shape[i];
        }
        return Tensor{
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .allocator = allocator,
        };
    }

    pub fn view(self: Tensor, start: usize, end: usize, allocator: std.mem.Allocator) !Tensor {
        const new_shape = try allocator.alloc(usize, 1);
        new_shape[0] = end - start;
        const new_strides = try allocator.alloc(usize, 1);
        new_strides[0] = 1;
        return Tensor{
            .data = self.data[start..end],
            .shape = new_shape,
            .strides = new_strides,
            .allocator = allocator,
        };
    }

    pub fn concatenate(allocator: std.mem.Allocator, tensors: []Tensor) !Tensor {
        var total_size: usize = 0;
        for (tensors) |t| {
            total_size += t.data.len;
        }
        const data = try allocator.alloc(f32, total_size);
        var offset: usize = 0;
        for (tensors) |t| {
            @memcpy(data[offset..offset + t.data.len], t.data);
            offset += t.data.len;
        }
        const shape = try allocator.alloc(usize, 1);
        shape[0] = total_size;
        const strides = try allocator.alloc(usize, 1);
        strides[0] = 1;
        return Tensor{
            .data = data,
            .shape = shape,
            .strides = strides,
            .allocator = allocator,
        };
    }

    pub fn matmulSIMD(self: Tensor, other: Tensor, allocator: std.mem.Allocator) !Tensor {
        if (self.shape.len != 2 or other.shape.len != 2) {
            return error.InvalidDimensions;
        }
        if (self.shape[1] != other.shape[0]) {
            return error.IncompatibleShapes;
        }
        const rows = self.shape[0];
        const cols = other.shape[1];
        const inner = self.shape[1];
        var result = try Tensor.zeros(allocator, &[_]usize{ rows, cols });
        const simd_width = 8;
        var i: usize = 0;
        while (i < rows) : (i += 1) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var sum: @Vector(simd_width, f32) = @splat(0.0);
                var k: usize = 0;
                while (k + simd_width <= inner) : (k += simd_width) {
                    var a_vec: @Vector(simd_width, f32) = undefined;
                    var b_vec: @Vector(simd_width, f32) = undefined;
                    inline for (0..simd_width) |idx| {
                        a_vec[idx] = self.data[i * inner + k + idx];
                        b_vec[idx] = other.data[(k + idx) * cols + j];
                    }
                    sum += a_vec * b_vec;
                }
                var scalar_sum: f32 = @reduce(.Add, sum);
                while (k < inner) : (k += 1) {
                    scalar_sum += self.data[i * inner + k] * other.data[k * cols + j];
                }
                result.data[i * cols + j] = scalar_sum;
            }
        }
        return result;
    }

    pub fn addSIMD(self: Tensor, other: Tensor, allocator: std.mem.Allocator) !Tensor {
        if (self.data.len != other.data.len) {
            return error.IncompatibleShapes;
        }
        var result = try Tensor.zeros(allocator, self.shape);
        const simd_width = 8;
        var i: usize = 0;
        while (i + simd_width <= self.data.len) : (i += simd_width) {
            var a_vec: @Vector(simd_width, f32) = undefined;
            var b_vec: @Vector(simd_width, f32) = undefined;
            inline for (0..simd_width) |idx| {
                a_vec[idx] = self.data[i + idx];
                b_vec[idx] = other.data[i + idx];
            }
            const sum_vec = a_vec + b_vec;
            inline for (0..simd_width) |idx| {
                result.data[i + idx] = sum_vec[idx];
            }
        }
        while (i < self.data.len) : (i += 1) {
            result.data[i] = self.data[i] + other.data[i];
        }
        return result;
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn deinitWithData(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }
};
