const std = @import("std");
const Tensor = @import("tensor.zig").Tensor;

pub const QuantumState = struct {
    amplitudes: []std.math.Complex(f32),
    num_qubits: usize,
    allocator: std.mem.Allocator,

    pub fn initZero(allocator: std.mem.Allocator, num_qubits: usize) !QuantumState {
        const size = @as(usize, 1) << @intCast(num_qubits);
        const amplitudes = try allocator.alloc(std.math.Complex(f32), size);
        for (amplitudes, 0..) |*amp, i| {
            if (i == 0) {
                amp.* = std.math.Complex(f32){ .re = 1.0, .im = 0.0 };
            } else {
                amp.* = std.math.Complex(f32){ .re = 0.0, .im = 0.0 };
            }
        }
        return QuantumState{
            .amplitudes = amplitudes,
            .num_qubits = num_qubits,
            .allocator = allocator,
        };
    }

    pub fn applyRYSIMD(self: *QuantumState, qubit: usize, angle: f32) !void {
        const cos_half = @cos(angle / 2.0);
        const sin_half = @sin(angle / 2.0);
        const size = @as(usize, 1) << @intCast(self.num_qubits);
        const stride = @as(usize, 1) << @intCast(qubit);
        const simd_width = 4;
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j + simd_width <= stride) : (j += simd_width) {
                var re0_vec: @Vector(simd_width, f32) = undefined;
                var im0_vec: @Vector(simd_width, f32) = undefined;
                var re1_vec: @Vector(simd_width, f32) = undefined;
                var im1_vec: @Vector(simd_width, f32) = undefined;
                inline for (0..simd_width) |k| {
                    const idx0 = i + j + k;
                    const idx1 = idx0 + stride;
                    re0_vec[k] = self.amplitudes[idx0].re;
                    im0_vec[k] = self.amplitudes[idx0].im;
                    re1_vec[k] = self.amplitudes[idx1].re;
                    im1_vec[k] = self.amplitudes[idx1].im;
                }
                const cos_vec: @Vector(simd_width, f32) = @splat(cos_half);
                const sin_vec: @Vector(simd_width, f32) = @splat(sin_half);
                const new_re0 = cos_vec * re0_vec - sin_vec * re1_vec;
                const new_im0 = cos_vec * im0_vec - sin_vec * im1_vec;
                const new_re1 = sin_vec * re0_vec + cos_vec * re1_vec;
                const new_im1 = sin_vec * im0_vec + cos_vec * im1_vec;
                inline for (0..simd_width) |k| {
                    const idx0 = i + j + k;
                    const idx1 = idx0 + stride;
                    self.amplitudes[idx0].re = new_re0[k];
                    self.amplitudes[idx0].im = new_im0[k];
                    self.amplitudes[idx1].re = new_re1[k];
                    self.amplitudes[idx1].im = new_im1[k];
                }
            }
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const amp0 = self.amplitudes[idx0];
                const amp1 = self.amplitudes[idx1];
                self.amplitudes[idx0] = std.math.Complex(f32){
                    .re = cos_half * amp0.re - sin_half * amp1.re,
                    .im = cos_half * amp0.im - sin_half * amp1.im,
                };
                self.amplitudes[idx1] = std.math.Complex(f32){
                    .re = sin_half * amp0.re + cos_half * amp1.re,
                    .im = sin_half * amp0.im + cos_half * amp1.im,
                };
            }
        }
    }

    pub fn applyRZ(self: *QuantumState, qubit: usize, angle: f32) !void {
        const exp_neg = std.math.Complex(f32){
            .re = @cos(-angle / 2.0),
            .im = @sin(-angle / 2.0),
        };
        const exp_pos = std.math.Complex(f32){
            .re = @cos(angle / 2.0),
            .im = @sin(angle / 2.0),
        };
        const size = @as(usize, 1) << @intCast(self.num_qubits);
        const simd_width = 4;
        var i: usize = 0;
        while (i + simd_width <= size) : (i += simd_width) {
            inline for (0..simd_width) |k| {
                const idx = i + k;
                const bit = (idx >> @intCast(qubit)) & 1;
                const phase = if (bit == 0) exp_neg else exp_pos;
                const amp = self.amplitudes[idx];
                self.amplitudes[idx] = std.math.Complex(f32){
                    .re = amp.re * phase.re - amp.im * phase.im,
                    .im = amp.re * phase.im + amp.im * phase.re,
                };
            }
        }
        while (i < size) : (i += 1) {
            const bit = (i >> @intCast(qubit)) & 1;
            const phase = if (bit == 0) exp_neg else exp_pos;
            const amp = self.amplitudes[i];
            self.amplitudes[i] = std.math.Complex(f32){
                .re = amp.re * phase.re - amp.im * phase.im,
                .im = amp.re * phase.im + amp.im * phase.re,
            };
        }
    }

    pub fn applyCNOT(self: *QuantumState, control: usize, target: usize) !void {
        const size = @as(usize, 1) << @intCast(self.num_qubits);
        const control_mask = @as(usize, 1) << @intCast(control);
        const target_mask = @as(usize, 1) << @intCast(target);
        var i: usize = 0;
        while (i < size) : (i += 1) {
            if ((i & control_mask) != 0) {
                const partner = i ^ target_mask;
                if (i < partner) {
                    const temp = self.amplitudes[i];
                    self.amplitudes[i] = self.amplitudes[partner];
                    self.amplitudes[partner] = temp;
                }
            }
        }
    }

    pub fn measure(self: *QuantumState, allocator: std.mem.Allocator) ![]f32 {
        const result = try allocator.alloc(f32, self.amplitudes.len);
        const simd_width = 8;
        var i: usize = 0;
        while (i + simd_width <= self.amplitudes.len) : (i += simd_width) {
            var re_vec: @Vector(simd_width, f32) = undefined;
            var im_vec: @Vector(simd_width, f32) = undefined;
            inline for (0..simd_width) |k| {
                re_vec[k] = self.amplitudes[i + k].re;
                im_vec[k] = self.amplitudes[i + k].im;
            }
            const prob_vec = re_vec * re_vec + im_vec * im_vec;
            inline for (0..simd_width) |k| {
                result[i + k] = prob_vec[k];
            }
        }
        while (i < self.amplitudes.len) : (i += 1) {
            const amp = self.amplitudes[i];
            result[i] = amp.re * amp.re + amp.im * amp.im;
        }
        return result;
    }

    pub fn deinit(self: *QuantumState) void {
        self.allocator.free(self.amplitudes);
    }
};

pub const QuantumCircuit = struct {
    num_qubits: usize,
    parameters: []f32,
    kernel_depth: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, num_qubits: usize) !QuantumCircuit {
        const kernel_depth = 6;
        const param_count = num_qubits * kernel_depth * 3;
        const parameters = try allocator.alloc(f32, param_count);
        var prng = std.rand.DefaultPrng.init(12345);
        const random_gen = prng.random();
        for (parameters) |*p| {
            p.* = random_gen.float(f32) * 2.0 * std.math.pi;
        }
        return QuantumCircuit{
            .num_qubits = num_qubits,
            .parameters = parameters,
            .kernel_depth = kernel_depth,
            .allocator = allocator,
        };
    }

    pub fn applyParameterizedGates(self: *QuantumCircuit, state: *QuantumState, layer: usize) !void {
        for (0..self.num_qubits) |q| {
            const param_idx = layer * self.num_qubits * 3 + q * 3;
            try state.applyRYSIMD(q, self.parameters[param_idx]);
            try state.applyRZ(q, self.parameters[param_idx + 1]);
            try state.applyRYSIMD(q, self.parameters[param_idx + 2]);
        }
    }

    pub fn applyEntanglement(self: *QuantumCircuit, state: *QuantumState) !void {
        for (0..self.num_qubits - 1) |q| {
            try state.applyCNOT(q, q + 1);
        }
    }

    pub fn fuseChannels(self: *QuantumCircuit, states: []QuantumState) !QuantumState {
        var fused = try QuantumState.initZero(self.allocator, self.num_qubits);
        const num_channels = states.len;
        const weight = 1.0 / @sqrt(@as(f32, @floatFromInt(num_channels)));
        for (states) |state| {
            for (state.amplitudes, 0..) |amp, i| {
                fused.amplitudes[i].re += amp.re * weight;
                fused.amplitudes[i].im += amp.im * weight;
            }
        }
        return fused;
    }

    pub fn updateParameters(self: *QuantumCircuit, gradients: []const f32) !void {
        const learning_rate: f32 = 0.01;
        const simd_width = 8;
        var i: usize = 0;
        while (i + simd_width <= self.parameters.len) : (i += simd_width) {
            var param_vec: @Vector(simd_width, f32) = undefined;
            var grad_vec: @Vector(simd_width, f32) = undefined;
            inline for (0..simd_width) |k| {
                param_vec[k] = self.parameters[i + k];
                grad_vec[k] = gradients[i + k];
            }
            const lr_vec: @Vector(simd_width, f32) = @splat(learning_rate);
            const new_param_vec = param_vec - lr_vec * grad_vec;
            inline for (0..simd_width) |k| {
                self.parameters[i + k] = new_param_vec[k];
            }
        }
        while (i < self.parameters.len) : (i += 1) {
            self.parameters[i] -= learning_rate * gradients[i];
        }
    }

    pub fn deinit(self: *QuantumCircuit) void {
        self.allocator.free(self.parameters);
    }
};

pub const MultiChannelQCNN = struct {
    num_channels: usize,
    num_qubits: usize,
    circuit: QuantumCircuit,
    arena: std.heap.ArenaAllocator,
    base_allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, channels: usize, qubits: usize) !MultiChannelQCNN {
        return MultiChannelQCNN{
            .num_channels = channels,
            .num_qubits = qubits,
            .circuit = try QuantumCircuit.init(allocator, qubits),
            .arena = std.heap.ArenaAllocator.init(allocator),
            .base_allocator = allocator,
        };
    }

    pub fn forward(self: *MultiChannelQCNN, input: []const Tensor) ![]f32 {
        defer _ = self.arena.reset(.retain_capacity);
        const arena_alloc = self.arena.allocator();
        var encoded_states = try arena_alloc.alloc(QuantumState, self.num_channels);
        for (input, 0..) |channel_data, i| {
            encoded_states[i] = try self.encodeChannel(arena_alloc, channel_data, i);
        }
        var fused = try self.circuit.fuseChannels(encoded_states);
        for (0..self.circuit.kernel_depth) |layer| {
            try self.circuit.applyParameterizedGates(&fused, layer);
            try self.circuit.applyEntanglement(&fused);
        }
        const measurement = try fused.measure(arena_alloc);
        const result = try self.base_allocator.alloc(f32, measurement.len);
        @memcpy(result, measurement);
        return result;
    }

    fn encodeChannel(self: *MultiChannelQCNN, arena_alloc: std.mem.Allocator, data: Tensor, channel_idx: usize) !QuantumState {
        _ = channel_idx;
        var state = try QuantumState.initZero(arena_alloc, self.num_qubits);
        for (0..@min(self.num_qubits, data.data.len)) |i| {
            const angle = data.data[i] * std.math.pi;
            try state.applyRYSIMD(i, angle);
        }
        return state;
    }

    pub fn deinit(self: *MultiChannelQCNN) void {
        self.circuit.deinit();
        self.arena.deinit();
    }
};
