const std = @import("std");
const Tensor = @import("tensor.zig").Tensor;

pub const PhotonicCore = struct {
    num_neurons: usize,
    wavelength_channels: usize,
    phase_modulators: []f32,
    amplitude_modulators: []f32,
    arena: std.heap.ArenaAllocator,
    base_allocator: std.mem.Allocator,
    thread_pool: std.Thread.Pool,

    pub fn init(allocator: std.mem.Allocator, neurons: usize) !PhotonicCore {
        const channels = 32;
        var pool: std.Thread.Pool = undefined;
        try pool.init(.{ .allocator = allocator });
        return PhotonicCore{
            .num_neurons = neurons,
            .wavelength_channels = channels,
            .phase_modulators = try allocator.alloc(f32, neurons * channels),
            .amplitude_modulators = try allocator.alloc(f32, neurons * channels),
            .arena = std.heap.ArenaAllocator.init(allocator),
            .base_allocator = allocator,
            .thread_pool = pool,
        };
    }

    pub fn processParallel(self: *PhotonicCore, input: Tensor) !Tensor {
        defer _ = self.arena.reset(.retain_capacity);
        const arena_alloc = self.arena.allocator();
        const num_chunks = self.thread_pool.threads.len;
        const chunk_size = (input.data.len + num_chunks - 1) / num_chunks;
        var results = try arena_alloc.alloc(Tensor, num_chunks);
        var wait_group = std.Thread.WaitGroup{};
        for (0..num_chunks) |chunk_idx| {
            const start = chunk_idx * chunk_size;
            const end = @min(start + chunk_size, input.data.len);
            if (start >= end) break;
            wait_group.start();
            try self.thread_pool.spawn(processChunk, .{ self, input, start, end, &results[chunk_idx], &wait_group });
        }
        self.thread_pool.waitAndWork(&wait_group);
        return try Tensor.concatenate(self.base_allocator, results);
    }

    fn processChunk(self: *PhotonicCore, input: Tensor, start: usize, end: usize, result: *Tensor, wg: *std.Thread.WaitGroup) void {
        defer wg.finish();
        const arena_alloc = self.arena.allocator();
        const chunk_data = input.data[start..end];
        var output_data = arena_alloc.alloc(f32, chunk_data.len) catch return;
        const simd_width = 8;
        var i: usize = 0;
        while (i + simd_width <= chunk_data.len) : (i += simd_width) {
            var phase_vec: @Vector(simd_width, f32) = undefined;
            var amp_vec: @Vector(simd_width, f32) = undefined;
            inline for (0..simd_width) |k| {
                const idx = start + i + k;
                phase_vec[k] = chunk_data[i + k] * self.phase_modulators[idx % self.phase_modulators.len];
                amp_vec[k] = @abs(chunk_data[i + k]) * self.amplitude_modulators[idx % self.amplitude_modulators.len];
            }
            const processed = @sin(phase_vec) * amp_vec;
            inline for (0..simd_width) |k| {
                output_data[i + k] = processed[k];
            }
        }
        while (i < chunk_data.len) : (i += 1) {
            const idx = start + i;
            const phase = chunk_data[i] * self.phase_modulators[idx % self.phase_modulators.len];
            const amp = @abs(chunk_data[i]) * self.amplitude_modulators[idx % self.amplitude_modulators.len];
            output_data[i] = @sin(phase) * amp;
        }
        result.* = Tensor.fromSlice(arena_alloc, output_data, &[_]usize{chunk_data.len}) catch return;
    }

    pub fn deinit(self: *PhotonicCore) void {
        self.base_allocator.free(self.phase_modulators);
        self.base_allocator.free(self.amplitude_modulators);
        self.arena.deinit();
        self.thread_pool.deinit();
    }
};

pub const CIMArray = struct {
    rows: usize,
    cols: usize,
    conductance: []f32,
    arena: std.heap.ArenaAllocator,
    base_allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, rows: usize, cols: usize) !CIMArray {
        const conductance = try allocator.alloc(f32, rows * cols);
        var prng = std.rand.DefaultPrng.init(55555);
        const random_gen = prng.random();
        for (conductance) |*val| {
            val.* = random_gen.float(f32) * 0.01;
        }
        return CIMArray{
            .rows = rows,
            .cols = cols,
            .conductance = conductance,
            .arena = std.heap.ArenaAllocator.init(allocator),
            .base_allocator = allocator,
        };
    }

    pub fn matmulSIMD(self: *CIMArray, vector: []const f32) ![]f32 {
        defer _ = self.arena.reset(.retain_capacity);
        const result = try self.base_allocator.alloc(f32, self.rows);
        const simd_width = 8;
        for (0..self.rows) |i| {
            var sum_vec: @Vector(simd_width, f32) = @splat(0.0);
            var j: usize = 0;
            while (j + simd_width <= @min(self.cols, vector.len)) : (j += simd_width) {
                var cond_vec: @Vector(simd_width, f32) = undefined;
                var vec_vec: @Vector(simd_width, f32) = undefined;
                inline for (0..simd_width) |k| {
                    cond_vec[k] = self.conductance[i * self.cols + j + k];
                    vec_vec[k] = vector[j + k];
                }
                sum_vec += cond_vec * vec_vec;
            }
            var scalar_sum = @reduce(.Add, sum_vec);
            while (j < @min(self.cols, vector.len)) : (j += 1) {
                scalar_sum += self.conductance[i * self.cols + j] * vector[j];
            }
            result[i] = scalar_sum;
        }
        return result;
    }

    pub fn deinit(self: *CIMArray) void {
        self.base_allocator.free(self.conductance);
        self.arena.deinit();
    }
};

pub const SSMCore = struct {
    state_dim: usize,
    A: []f32,
    B: []f32,
    C: []f32,
    hidden_state: []f32,
    cim_array: CIMArray,
    arena: std.heap.ArenaAllocator,
    base_allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, state_dim: usize) !SSMCore {
        const A = try allocator.alloc(f32, state_dim * state_dim);
        const B = try allocator.alloc(f32, state_dim * state_dim);
        const C = try allocator.alloc(f32, state_dim * state_dim);
        const hidden_state = try allocator.alloc(f32, state_dim);
        var prng = std.rand.DefaultPrng.init(44444);
        const random_gen = prng.random();
        for (A) |*val| val.* = random_gen.float(f32) * 0.1;
        for (B) |*val| val.* = random_gen.float(f32) * 0.1;
        for (C) |*val| val.* = random_gen.float(f32) * 0.1;
        @memset(hidden_state, 0.0);
        return SSMCore{
            .state_dim = state_dim,
            .A = A,
            .B = B,
            .C = C,
            .hidden_state = hidden_state,
            .cim_array = try CIMArray.init(allocator, state_dim, state_dim),
            .arena = std.heap.ArenaAllocator.init(allocator),
            .base_allocator = allocator,
        };
    }

    pub fn processSequence(self: *SSMCore, input: []const f32) ![]f32 {
        defer _ = self.arena.reset(.retain_capacity);
        const arena_alloc = self.arena.allocator();
        const output = try arena_alloc.alloc(f32, input.len);
        for (input, 0..) |x, t| {
            const A_h = try self.cim_array.matmulSIMD(self.hidden_state);
            defer self.base_allocator.free(A_h);
            const B_x = try self.cim_array.matmulSIMD(&[_]f32{x});
            defer self.base_allocator.free(B_x);
            const simd_width = 8;
            var i: usize = 0;
            while (i + simd_width <= self.state_dim) : (i += simd_width) {
                var ah_vec: @Vector(simd_width, f32) = undefined;
                var bx_vec: @Vector(simd_width, f32) = undefined;
                inline for (0..simd_width) |k| {
                    ah_vec[k] = if (i + k < A_h.len) A_h[i + k] else 0.0;
                    bx_vec[k] = if (i + k < B_x.len) B_x[i + k] else 0.0;
                }
                const new_hidden = ah_vec + bx_vec;
                inline for (0..simd_width) |k| {
                    self.hidden_state[i + k] = new_hidden[k];
                }
            }
            while (i < self.state_dim) : (i += 1) {
                self.hidden_state[i] = (if (i < A_h.len) A_h[i] else 0.0) + (if (i < B_x.len) B_x[i] else 0.0);
            }
            const C_h = try self.cim_array.matmulSIMD(self.hidden_state);
            defer self.base_allocator.free(C_h);
            output[t] = if (C_h.len > 0) C_h[0] else 0.0;
        }
        const result = try self.base_allocator.alloc(f32, output.len);
        @memcpy(result, output);
        return result;
    }

    pub fn deinit(self: *SSMCore) void {
        self.base_allocator.free(self.A);
        self.base_allocator.free(self.B);
        self.base_allocator.free(self.C);
        self.base_allocator.free(self.hidden_state);
        self.cim_array.deinit();
        self.arena.deinit();
    }
};

pub const AiMXChip = struct {
    chip_id: usize,
    memory_banks: [8][]f32,
    pim_units: [64]PIMUnit,
    thread_pool: std.Thread.Pool,
    arena: std.heap.ArenaAllocator,
    base_allocator: std.mem.Allocator,

    pub const PIMUnit = struct {
        unit_id: usize,

        pub fn matmul(self: PIMUnit, input: []const f32, weights: []const f32, output: []f32) void {
            _ = self;
            const output_size = output.len;
            const input_size = input.len;
            const simd_width = 8;
            for (0..output_size) |i| {
                var sum_vec: @Vector(simd_width, f32) = @splat(0.0);
                var j: usize = 0;
                while (j + simd_width <= input_size) : (j += simd_width) {
                    var inp_vec: @Vector(simd_width, f32) = undefined;
                    var w_vec: @Vector(simd_width, f32) = undefined;
                    inline for (0..simd_width) |k| {
                        inp_vec[k] = input[j + k];
                        const w_idx = i * input_size + j + k;
                        w_vec[k] = if (w_idx < weights.len) weights[w_idx] else 0.0;
                    }
                    sum_vec += inp_vec * w_vec;
                }
                var scalar_sum = @reduce(.Add, sum_vec);
                while (j < input_size) : (j += 1) {
                    const w_idx = i * input_size + j;
                    scalar_sum += input[j] * (if (w_idx < weights.len) weights[w_idx] else 0.0);
                }
                output[i] = scalar_sum;
            }
        }
    };

    pub fn init(allocator: std.mem.Allocator, chip_id: usize) !AiMXChip {
        var memory_banks: [8][]f32 = undefined;
        for (&memory_banks, 0..) |*bank, i| {
            bank.* = try allocator.alloc(f32, 1048576);
            var prng = std.rand.DefaultPrng.init(@intCast(chip_id * 8 + i));
            const random_gen = prng.random();
            for (bank.*) |*val| {
                val.* = random_gen.float(f32) * 0.01;
            }
        }
        var pim_units: [64]PIMUnit = undefined;
        for (&pim_units, 0..) |*unit, i| {
            unit.* = PIMUnit{ .unit_id = i };
        }
        var pool: std.Thread.Pool = undefined;
        try pool.init(.{ .allocator = allocator });
        return AiMXChip{
            .chip_id = chip_id,
            .memory_banks = memory_banks,
            .pim_units = pim_units,
            .thread_pool = pool,
            .arena = std.heap.ArenaAllocator.init(allocator),
            .base_allocator = allocator,
        };
    }

    pub fn transformerLayer(self: *AiMXChip, input: []const f32) ![]f32 {
        defer _ = self.arena.reset(.retain_capacity);
        const arena_alloc = self.arena.allocator();
        const hidden_dim = 4096;
        const qkv = try arena_alloc.alloc(f32, hidden_dim * 3);
        var wait_group = std.Thread.WaitGroup{};
        wait_group.start();
        try self.thread_pool.spawn(computeQKV, .{ self, input, qkv, &wait_group });
        self.thread_pool.waitAndWork(&wait_group);
        const output = try self.base_allocator.alloc(f32, hidden_dim);
        @memcpy(output[0..@min(hidden_dim, qkv.len)], qkv[0..@min(hidden_dim, qkv.len)]);
        return output;
    }

    fn computeQKV(self: *AiMXChip, input: []const f32, output: []f32, wg: *std.Thread.WaitGroup) void {
        defer wg.finish();
        const bank_idx = self.chip_id % 8;
        const weights = self.memory_banks[bank_idx];
        self.pim_units[0].matmul(input, weights, output);
    }

    pub fn deinit(self: *AiMXChip) void {
        for (&self.memory_banks) |*bank| {
            self.base_allocator.free(bank.*);
        }
        self.thread_pool.deinit();
        self.arena.deinit();
    }
};
